import { readFileSync } from 'node:fs';
import { formatOrder } from '../src/format-order.js';

const orders = JSON.parse(
  readFileSync(new URL('../data/orders.json', import.meta.url), 'utf8'),
);
for (const order of orders) {
  console.log(formatOrder(order));
  console.log('---');
}

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { cpSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { formatOrder, orderTotal } from '../src/format-order.js';

const root = process.cwd();

// 1) The crash case is fixed: an order without a gift note formats cleanly.
const plain = {
  id: 'A-1042',
  customer: 'Ben Ito',
  items: [{ qty: 2, name: 'Stone Mug', unitPrice: 9.5 }],
};
const plainReceipt = formatOrder(plain);
assert.ok(!plainReceipt.includes('undefined'), 'a receipt must not leak "undefined"');
assert.ok(!/Gift note:/.test(plainReceipt), 'an order without a gift note must not print a gift-note line');
assert.ok(plainReceipt.includes('Total: 19.00'), 'totals must survive the patch');
console.log('HOTFIX_ORACLE crash case fixed');

// 2) Neighborhood intact: gift notes still print trimmed, totals still add up.
const gifted = {
  id: 'A-1041',
  customer: 'Ana Torres',
  items: [{ qty: 1, name: 'Ceramic Vase', unitPrice: 30 }],
  giftNote: '  Happy birthday, Ana!  ',
};
const giftedReceipt = formatOrder(gifted);
assert.ok(giftedReceipt.includes('Gift note: Happy birthday, Ana!'), 'gift notes must still print, trimmed');
const multi = {
  id: 'A-1043',
  customer: 'Priya Shah',
  items: [
    { qty: 3, name: 'Linen Napkin', unitPrice: 4 },
    { qty: 1, name: 'Oak Tray', unitPrice: 18 },
  ],
};
assert.equal(orderTotal(multi), 30, 'orderTotal must be untouched');
console.log('HOTFIX_ORACLE neighborhood intact');

// 3) The export the incident names runs clean end to end.
const exportOut = execFileSync(process.execPath, ['scripts/print-receipts.mjs'], {
  cwd: root,
  stdio: 'pipe',
  timeout: 30000,
}).toString();
assert.ok(exportOut.includes('A-1043'), 'the export must reach the last order');
console.log('HOTFIX_ORACLE export green');

// 4) Re-seed the original defect into a mutant tree: the crash must come
// back, proving the patch engaged the real site rather than the callers
// or the data (both of which are pinned fixtures anyway).
const ORIGINAL = `export function formatOrder(order) {
  const lines = [];
  lines.push('Order ' + order.id + ' for ' + order.customer);
  for (const item of order.items) {
    lines.push('  ' + item.qty + ' x ' + item.name + ' @ ' + money(item.unitPrice));
  }
  lines.push('Total: ' + money(orderTotal(order)));
  lines.push('Gift note: ' + order.giftNote.trim());
  return lines.join('\\n');
}

export function orderTotal(order) {
  let total = 0;
  for (const item of order.items) {
    total += item.qty * item.unitPrice;
  }
  return Math.round(total * 100) / 100;
}

function money(value) {
  return value.toFixed(2);
}
`;
const mutantRoot = join(root, '.oracle-mutant');
rmSync(mutantRoot, { recursive: true, force: true });
mkdirSync(join(mutantRoot, 'src'), { recursive: true });
cpSync(join(root, 'scripts'), join(mutantRoot, 'scripts'), { recursive: true });
cpSync(join(root, 'data'), join(mutantRoot, 'data'), { recursive: true });
cpSync(join(root, 'package.json'), join(mutantRoot, 'package.json'));
writeFileSync(join(mutantRoot, 'src', 'format-order.js'), ORIGINAL);
let mutantStatus = 0;
try {
  execFileSync(process.execPath, ['scripts/print-receipts.mjs'], {
    cwd: mutantRoot,
    stdio: 'pipe',
    timeout: 30000,
  });
} catch (err) {
  mutantStatus = typeof err.status === 'number' ? err.status : 1;
}
assert.notEqual(mutantStatus, 0, 're-seeding the original defect must restore the crash - the patch did not engage the real site');
console.log('HOTFIX_ORACLE mutant caught');
console.log('HOTFIX_ORACLE done');
